fulfill.run:
// 标记为区块根节点，供子孙节点通过 $utils.getBlockRootField 反查（不受组件拖动影响）
$utils.setAsBlockRoot($self)
// 区块路径
const rootEntire = $self.address.entire

// 修复 Div 包裹时 FormItem 底部间距
$utils.fixAntFormilyItemMarginBottom($self, $effect)

// 与翻译设置「单词本管理」共用同一存储结构与 key，实现单词数据互通复用
// 存储：chrome.storage.local 的 'translationWordbook'，元素结构 { source, translation, time }
const STORAGE_KEY = 'translationWordbook'
const MAX_COUNT = 200

$self.state = $observable({ list: null })

// 展示页面内通知和系统通知
const sendNotification = (item) => {
  $message.success(`${item.source} ${item.translation}`)

  // 创建系统通知
  $chrome.notifications.create(
    null,
    {
      type: "basic",
      title: item.source,
      message: item.translation,
      iconUrl:
        "https://d35aaqx5ub95lt.cloudfront.net/images/pathCharacters/guidebook/939ebad747027f1a9d365e15fda3a4e1.svg",
    },
    $chrome.proxy((notificationId) => {
      // 延迟 6 秒清除系统通知
      setTimeout(() => {
        $chrome.notifications.clear(notificationId)
      }, 6000)
    })
  )
}

$self.crud = {
  // 条目中文名称
  itemChineseName: "自定义单词",
  // 条目表格组件的名称
  itemTableName: `customWordTable`,
  // 添加或修改对话框的名称
  addOrUpdateDialogName: `addOrUpdateCustomWordDialog`,
  // 展示添加或修改条目对话框
  showAddOrUpdateDialog(toAddOrUpdateItem) {
    const addOrUpdateDialog = $self
      .query(`${rootEntire}.${this.addOrUpdateDialogName}`)
      .take()
    if (!addOrUpdateDialog) return
    addOrUpdateDialog.value = {
      source: (toAddOrUpdateItem && toAddOrUpdateItem.source) || "",
      translation: (toAddOrUpdateItem && toAddOrUpdateItem.translation) || "",
      __editIndex: toAddOrUpdateItem ? toAddOrUpdateItem.__index : -1,
    }
    addOrUpdateDialog.setComponentProps({
      open: true,
      title: `${toAddOrUpdateItem ? "修改" : "添加"}${this.itemChineseName}`,
    })
  },
  // 添加或修改条目（校验、去重、超限截断，与翻译设置「单词本管理」一致）
  async addOrUpdateItem(toAddOrUpdateItem) {
    const source = (toAddOrUpdateItem.source || "").trim()
    if (!source) {
      $message.error("源文不能为空")
      return false
    }
    const translation = (toAddOrUpdateItem.translation || "").trim()
    if (!translation) {
      $message.error("译文不能为空")
      return false
    }

    const list = (await this.fetchItemList()).slice()
    const editIndex = toAddOrUpdateItem.__editIndex

    if (editIndex != null && editIndex >= 0 && editIndex < list.length) {
      // 修改：按 __index 就地替换
      list[editIndex] = { ...list[editIndex], source, translation }
    } else {
      // 添加：按 source + translation 组合去重，头插，超 200 条截断最旧
      if (
        list.some(
          (item) => item.source === source && item.translation === translation
        )
      ) {
        $message.error("该单词已存在")
        return false
      }
      list.unshift({ source, translation, time: Date.now() })
      if (list.length > MAX_COUNT) list.length = MAX_COUNT
    }

    await this.saveItemList(list)
    $message.success(
      editIndex != null && editIndex >= 0 ? "修改成功" : "添加成功"
    )
    return true
  },
  // 删除条目（按 __index 定位）
  async deleteItem(toDeleteItem) {
    const list = (await this.fetchItemList()).slice()
    const index = toDeleteItem.__index
    if (index == null || index < 0 || index >= list.length) return
    list.splice(index, 1)
    await this.saveItemList(list)
    $message.success("删除成功")
  },
  // 往前移动条目（按 __index 定位，重排后保存，表格自动按新顺序渲染）
  async moveUpItem(toMoveItem) {
    const list = (await this.fetchItemList()).slice()
    const index = toMoveItem.__index
    if (index == null || index < 0 || index >= list.length) return
    let preIndex = index - 1
    if (preIndex === -1) {
      // 已经是第一条，则和最后一条互换
      preIndex = list.length - 1
    }
    const other = list[preIndex]
    list[preIndex] = list[index]
    list[index] = other
    await this.saveItemList(list)
  },
  // 往后移动条目（按 __index 定位）
  async moveDownItem(toMoveItem) {
    const list = (await this.fetchItemList()).slice()
    const index = toMoveItem.__index
    if (index == null || index < 0 || index >= list.length) return
    let nextIndex = index + 1
    if (nextIndex === list.length) {
      // 已经是最后一条，则和第一条互换
      nextIndex = 0
    }
    const other = list[nextIndex]
    list[nextIndex] = list[index]
    list[index] = other
    await this.saveItemList(list)
  },
  // 保存条目列表数据（深拷贝拍平后写入 storage.local，并回写内存状态）
  async saveItemList(newItemList) {
    const plain = JSON.parse(JSON.stringify(newItemList || []))
    await $chrome.storage.local.set({ [STORAGE_KEY]: plain })
    $self.state.list = plain
    this.sendRandomNotification(plain)
  },
  // 获取条目列表（内存缓存 + storage.local，与翻译设置「单词本管理」同源）
  async fetchItemList(force) {
    if (!force && Array.isArray($self.state.list)) return $self.state.list
    const res = await $chrome.storage.local.get(STORAGE_KEY)
    const list = res && Array.isArray(res[STORAGE_KEY]) ? res[STORAGE_KEY] : []
    $self.state.list = list
    return list
  },
  // 随机播报一条单词
  sendRandomNotification(itemList) {
    if (!itemList || itemList.length === 0) return
    const randomIndex = parseInt(Math.random() * itemList.length)
    sendNotification(itemList[randomIndex])
  },
}

$effect(() => {
  (async () => {
    await $self.crud.fetchItemList()
    $self.crud.sendRandomNotification($self.state.list)
  })()
}, [])

const rootField = $utils.getBlockRootField($self)

$props({
  onClick: () => {
    const row = $utils.getArrayFieldRow($self, "ArrayTable")
    rootField.crud.deleteItem(row)
  },
})

const rootField = $utils.getBlockRootField($self)

$props({
  onClick: () => {
    const row = $utils.getArrayFieldRow($self, "ArrayTable")
    rootField.crud.moveUpItem(row)
  },
})

const rootField = $utils.getBlockRootField($self)

$props({
  onClick: () => {
    const row = $utils.getArrayFieldRow($self, "ArrayTable")
    rootField.crud.moveDownItem(row)
  },
})

const rootField = $utils.getBlockRootField($self)

$props({
  onClick: () => {
    const row = $utils.getArrayFieldRow($self, "ArrayTable")
    rootField.crud.showAddOrUpdateDialog(row)
  },
})

const rootField = $utils.getBlockRootField($self)

$props({
  // 点击取消按钮
  onCancel: () => {
    $self.componentProps.open = false
  },
  // 点击确认按钮
  onOk: () => {
    $self
      .validate() // 校验
      .then(async () => {
        const itemForm = $self.value

        // 添加或更新条目，成功后才关闭当前对话框
        const ok = await rootField.crud.addOrUpdateItem({
          ...itemForm
        })
        if (ok) {
          $self.componentProps.open = false
        }
      })
      .catch((e) => {
        $logger.info("表单校验失败", e)
      })
  },
})
